{
  "case_id": "xsu_sg_001_general_conditions",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "De tre betingelsesled (almindelige SU/slutlån-betingelser, videregående uddannelse eller dansk EUD, varig funktionsnedsættelse med meget betydelige begrænsninger i erhvervsevnen) stemmer med vejledningen og rubrikken. Tilføjelsen om ret til SU og indskrivning/gennemførelse af en SU-berettigende uddannelse understøttes af afsnit 3.2.1. Der er ingen væsentlige juridiske fejl."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "De tre centrale betingelsesled er med. Det første kritiske element kræver dog også, at handicaptillægget udbetales sammen med SU-stipendium eller slutlån. Det nævnes ikke. Svaret siger kun, at man skal opfylde betingelserne for SU eller slutlån og have ret til SU. Det er ikke det samme som at sige, at tillægget gives sammen med stipendium eller slutlån. Det andet element er kun delvist dækket: svaret nævner uddannelsen, men udtrykker ikke tydeligt, at man skal være indskrevet på en videregående uddannelse eller EUD."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret angiver direkte betingelserne for handicaptillæg, som spørgsmålet beder om."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret nævner ingen identificerbar kilde, hverken lov, bestemmelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Svaret angiver ingen kilde, så kildens gyldighed kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Svaret angiver ingen kilde, så det kan ikke vurderes, om en kilde understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Alle påstande har støtte i vejledningen afsnit 3.1 og 3.2.1 samt SU-lovens § 7, stk. 3. Svaret tilføjer ingen ustøttet regel."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Rubrikken kræver ingen særskilt standardadvarsel. Svaret bevarer 'varig' og 'meget betydelige begrænsninger'. Det angiver ikke betingelserne som udtømmende almindelige SU-betingelser, og det er acceptabelt."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Opremsningen er sammenhængende. Det afsluttende afsnit om ret til SU gentager og præciserer den første betingelse uden at modsige noget."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "'Skal' bruges om betingelserne, hvilket svarer til kilderne. Svaret gør ikke skønsmæssige elementer absolutte."
    }
  },
  "xhaile_coverage": {
    "A1": {
      "label": "yes",
      "reason": "Svaret angiver som betingelse nr. 1, at man skal opfylde de almindelige betingelser for SU eller slutlån."
    },
    "A2": {
      "label": "partial",
      "reason": "Svaret nævner videregående uddannelse eller dansk EUD. Det forklarer ikke EUD-afgrænsningen, inklusive EUX og udelukkelsen af erhvervslignende udenlandske uddannelser."
    },
    "A3": {
      "label": "yes",
      "reason": "Svaret angiver betingelsen om varig fysisk eller psykisk funktionsnedsættelse med meget betydelige begrænsninger i evnen til erhvervsarbejde næsten ordret."
    },
    "A4": {
      "label": "yes",
      "reason": "Svaret angiver, at man skal have ret til SU og være indskrevet på og gennemgå en uddannelse, der berettiger til SU eller slutlån."
    },
    "A6": {
      "label": "no",
      "reason": "Svaret nævner ikke EUX og heller ikke, at erhvervslignende udenlandske uddannelser er udelukket fra EUD-afgrænsningen."
    }
  },
  "overall_notes": "Indholdsmæssigt er svaret korrekt og dækker de tre hovedbetingelser. Det mangler, at tillægget udbetales sammen med SU-stipendium eller slutlån, og det angiver ingen kilder. Derfor er C02 not_met, C04 not_met, og C05 og C06 er not_assessable."
}

